/**
 * The portal block of an ejected project (ADR 0077 D4, D9), in `<package>/portal/`: `PortalSpec`
 * (a portal's fields with the defaults applied, as the runtime's `BlockType.Portal`) and
 * `PortalBlock`, a copy of the runtime's `MsmPortalBlock`
 * (`engine-mod/src/main/java/dev/mcsupermods/runtime/registry/types/`, Minecraft 26.3, Mojang
 * names) built from a `PortalSpec` instead of a definition, with no behaviour driver: each portal
 * definition becomes a generated `block/<Name>Block` subclass that adds the ADR 0061 triggers a
 * portal may carry (after vanilla's and the portal's own behaviour, as the driver runs them) and
 * overrides `onTravel` for `on_travel`. The generator's tests compare every other code line with
 * the runtime's.
 *
 * @packageDocumentation
 */

/** The source of `PortalBlock.java`, copied from the runtime's `MsmPortalBlock`. */
export function portalBlockJava(portalPackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's MsmPortalBlock.
package ${portalPackage};

import java.util.Optional;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.particles.DustParticleOptions;
import net.minecraft.core.particles.ParticleOptions;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.core.particles.SimpleParticleType;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.tags.TagKey;
import net.minecraft.util.RandomSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.InsideBlockEffectApplier;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.LevelReader;
import net.minecraft.world.level.ScheduledTickAccess;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.Portal;
import net.minecraft.world.level.block.Rotation;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.block.state.properties.EnumProperty;
import net.minecraft.world.level.gamerules.GameRules;
import net.minecraft.world.level.portal.TeleportTransition;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.VoxelShape;

/**
 * A portal block ({@code type: "portal"}, ADR 0077 D4), written from the ADR's rules: state {@link #AXIS}, a thin shape
 * along the axis and no collision (the properties in {@code ModBlocks}), turned to air when the frame around it (D2) is no longer
 * whole; entities inside are handed to vanilla's portal processing through {@link Portal}. Lighting is
 * {@link PortalLighting} (D3); travel is {@link PortalTravel} (D6). The block of each portal definition is a generated
 * subclass that adds its own events.
 */
public class PortalBlock extends Block implements Portal {
    public static final EnumProperty<Direction.Axis> AXIS = BlockStateProperties.HORIZONTAL_AXIS;
    /** Light when {@code msm:light_emitter} is absent (ADR 0077 D1, the Nether portal's). */
    public static final int DEFAULT_LIGHT = 11;
    /** About one ambient sound in this many animation ticks (ADR 0077 D4). */
    public static final int AMBIENT_ONE_IN = 100;

    /** 4 pixels thick, centred, spanning the block along the axis. */
    private static final VoxelShape SHAPE_X = Block.box(0, 0, 6, 16, 16, 10);
    private static final VoxelShape SHAPE_Z = Block.box(6, 0, 0, 10, 16, 16);

    private final PortalSpec portal;
    private final ParticleOptions particle;
    private final SoundEvent ambient;
    private final TagKey<Block> frameTag;
    private final TagKey<Item> igniterTag;

    public PortalBlock(PortalSpec portal, Properties properties) {
        super(properties);
        this.portal = portal;
        this.particle = particle(portal.particles()).orElse(ParticleTypes.PORTAL);
        this.ambient = portal.sounds().ambient().off() ? null
                : portal.sounds().ambient().sound().map(s -> BuiltInRegistries.SOUND_EVENT.getOptional(s).orElse(null))
                        .orElse(SoundEvents.PORTAL_AMBIENT);
        this.frameTag = portal.frame().tag() ? TagKey.create(Registries.BLOCK, portal.frame().id()) : null;
        this.igniterTag = portal.igniter().filter(PortalSpec.IdOrTag::tag).map(t -> TagKey.create(Registries.ITEM, t.id())).orElse(null);
        registerDefaultState(stateDefinition.any().setValue(AXIS, Direction.Axis.X));
    }

    /**
     * The particle of {@code particles}: dust of {@code color} when set, else {@code type} when it is a particle type
     * without options, else the target's portal particle (absent {@code type}). Empty when {@code type} is unknown or
     * takes options (a load error: the default particle is used).
     */
    public static Optional<ParticleOptions> particle(PortalSpec.Particles particles) {
        if (particles.color().isPresent()) {
            return Optional.of(new DustParticleOptions(particles.color().get(), 1.0f));
        }
        if (particles.type().isEmpty()) {
            return Optional.of(ParticleTypes.PORTAL);
        }
        Identifier type = particles.type().get();
        if (BuiltInRegistries.PARTICLE_TYPE.containsKey(type) && BuiltInRegistries.PARTICLE_TYPE.getValue(type) instanceof SimpleParticleType simple) {
            return Optional.of(simple);
        }
        return Optional.empty();
    }

    /** The block's registry id. */
    public Identifier id() {
        return BuiltInRegistries.BLOCK.getKey(this);
    }

    /**
     * {@code on_travel}: called by {@link PortalTravel} after arrival with the arrived entity; a generated portal block
     * with {@code on_travel} fires its event here.
     */
    protected void onTravel(ServerLevel level, Entity arrived) {}

    /** The definition's portal fields. */
    public PortalSpec portal() {
        return portal;
    }

    /** The particle {@link #animateTick} spawns. */
    public ParticleOptions particle() {
        return particle;
    }

    /** The ambient sound, or null for none. */
    public SoundEvent ambientSound() {
        return ambient;
    }

    /** Whether {@code state} is a frame block: the {@code frame} block, or a block in the {@code frame} tag (read now). */
    public boolean isFrame(BlockState state) {
        if (frameTag != null) {
            return state.is(frameTag);
        }
        Optional<Block> frame = BuiltInRegistries.BLOCK.getOptional(portal.frame().id());
        return frame.isPresent() && frame.get() != Blocks.AIR && state.is(frame.get());
    }

    /** Whether {@code stack} is this portal's igniter (never with {@code igniter: false}). */
    public boolean isIgniter(ItemStack stack) {
        if (stack.isEmpty() || portal.igniter().isEmpty()) {
            return false;
        }
        if (igniterTag != null) {
            return stack.is(igniterTag);
        }
        return BuiltInRegistries.ITEM.getKey(stack.getItem()).equals(portal.igniter().get().id());
    }

    @Override
    protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) {
        builder.add(AXIS);
    }

    @Override
    protected VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext context) {
        return state.getValue(AXIS) == Direction.Axis.Z ? SHAPE_Z : SHAPE_X;
    }

    /**
     * A change beside the portal along its axis, or above or below it, turns it to air unless the frame around it is still
     * whole and lit all through (D4); a lone portal block (a {@code /setblock}) stays until such a change.
     */
    @Override
    protected BlockState updateShape(BlockState state, LevelReader level, ScheduledTickAccess ticks, BlockPos pos, Direction direction,
            BlockPos neighbourPos, BlockState neighbourState, RandomSource random) {
        Direction.Axis axis = state.getValue(AXIS);
        if ((direction.getAxis() == Direction.Axis.Y || direction.getAxis() == axis) && level instanceof LevelAccessor accessor) {
            Optional<PortalFrame.Rectangle> frame = PortalFrame.find(accessor, pos, axis, this::isFrame, this);
            if (frame.isEmpty() || !PortalFrame.isComplete(accessor, frame.get(), this)) {
                return Blocks.AIR.defaultBlockState();
            }
        }
        return super.updateShape(state, level, ticks, pos, direction, neighbourPos, neighbourState, random);
    }

    @Override
    protected BlockState rotate(BlockState state, Rotation rotation) {
        return switch (rotation) {
            case CLOCKWISE_90, COUNTERCLOCKWISE_90 ->
                    state.setValue(AXIS, state.getValue(AXIS) == Direction.Axis.X ? Direction.Axis.Z : Direction.Axis.X);
            default -> state;
        };
    }

    /**
     * On both sides, as vanilla's portal (the client's own player also keeps a portal process for its overlay): an entity
     * that may use a portal is marked inside this one, unless {@code players_only} keeps a non-player out (a cooling entity
     * keeps {@code cooldown_ticks} rather than vanilla's default); then
     * {@code msm:on_entity_inside}.
     */
    @Override
    protected void entityInside(BlockState state, Level level, BlockPos pos, Entity entity, InsideBlockEffectApplier effects,
            boolean intersects) {
        if (entity.canUsePortal(false) && (!portal.travel().playersOnly() || entity instanceof Player)) {
            boolean cooling = entity.isOnPortalCooldown();
            entity.setAsInsidePortal(this, pos);
            if (cooling) {
                // Vanilla refreshes a cooling entity's cooldown to its default while it stands in a portal (an arrival
                // standing in its exit); with cooldown_ticks the refresh uses that number instead (ADR 0077 D6).
                portal.travel().cooldownTicks().ifPresent(entity::setPortalCooldown);
            }
        }
    }

    /**
     * Players: an invulnerable (creative) player waits the gamerule {@code players_nether_portal_creative_delay}, any other
     * {@code delay_ticks} or the gamerule {@code players_nether_portal_default_delay}; everyone else goes at once.
     */
    @Override
    public int getPortalTransitionTime(ServerLevel level, Entity entity) {
        if (entity instanceof Player player) {
            GameRules rules = level.getGameRules();
            if (player.getAbilities().invulnerable) {
                return rules.get(GameRules.PLAYERS_NETHER_PORTAL_CREATIVE_DELAY);
            }
            return portal.travel().delayTicks().orElseGet(() -> rules.get(GameRules.PLAYERS_NETHER_PORTAL_DEFAULT_DELAY));
        }
        return 0;
    }

    /**
     * Where {@code entity} goes (D6, {@link PortalTravel}): {@code destination}, or {@code return_to} from it; a linked
     * exit portal or the surface; null (vanilla then sets the cooldown and moves nobody) for a missing level.
     */
    @Override
    public TeleportTransition getPortalDestination(ServerLevel level, Entity entity, BlockPos pos) {
        return PortalTravel.destination(this, level, entity, pos);
    }

    /** {@code overlay} (default true): vanilla's wobble, overlay and entry sound on the client; else none (limit P2). */
    @Override
    public Portal.Transition getLocalTransition() {
        return portal.travel().overlay() ? Portal.Transition.CONFUSION : Portal.Transition.NONE;
    }

    /** Client: {@code count} particles in the block and, about once in {@value #AMBIENT_ONE_IN} ticks, the ambient sound. */
    @Override
    public void animateTick(BlockState state, Level level, BlockPos pos, RandomSource random) {
        if (ambient != null && random.nextInt(AMBIENT_ONE_IN) == 0) {
            level.playLocalSound(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5, ambient, SoundSource.BLOCKS, 0.5f,
                    0.8f + random.nextFloat() * 0.4f, false);
        }
        boolean dust = particle instanceof DustParticleOptions;
        for (int i = 0; i < portal.particles().count(); i++) {
            double x = pos.getX() + random.nextDouble();
            double y = pos.getY() + random.nextDouble();
            double z = pos.getZ() + random.nextDouble();
            double speed = dust ? 0 : 0.5;
            level.addParticle(particle, x, y, z, (random.nextDouble() - 0.5) * speed, (random.nextDouble() - 0.5) * speed,
                    (random.nextDouble() - 0.5) * speed);
        }
    }

    /** Nothing to pick unless the definition gives the portal an {@code item}. */
    @Override
    protected ItemStack getCloneItemStack(LevelReader level, BlockPos pos, BlockState state, boolean includeData) {
        return asItem() == Items.AIR ? ItemStack.EMPTY : super.getCloneItemStack(level, pos, state, includeData);
    }
}
`;
}

/** The source of `PortalSpec.java`: a portal's fields, as the runtime's `BlockType.Portal`. */
export function portalSpecJava(portalPackage: string): string {
  return `// Generated by MCSuperMods: a portal's fields, as msm_runtime's BlockType.Portal.
package ${portalPackage};

import java.util.Optional;
import net.minecraft.resources.Identifier;

/**
 * A portal's fields (ADR 0077 D1) with the defaults applied: the frame block or block tag (read at use time, so tags
 * follow {@code /reload}), {@code frame_block} as written, the igniter item or item tag (empty for
 * {@code igniter: false}), the two dimensions, travel, sounds, particles and the {@code on_travel} event.
 */
public record PortalSpec(IdOrTag frame, Optional<Identifier> frameBlockSetting, Optional<IdOrTag> igniter, Identifier destination,
        Identifier returnTo, Travel travel, Sounds sounds, Particles particles, Optional<Identifier> onTravel) {

    /**
     * The block exits are built of: {@code frame_block}, else the {@code frame} block (a tag {@code frame} always has
     * {@code frame_block}: the generator requires it).
     */
    public Optional<Identifier> frameBlock() {
        return frameBlockSetting.isPresent() ? frameBlockSetting : frame.tag() ? Optional.empty() : Optional.of(frame.id());
    }

    /** A block or item id, or a tag id when {@code tag} is set. */
    public record IdOrTag(Identifier id, boolean tag) {
        @Override
        public String toString() {
            return tag ? "#" + id : id.toString();
        }
    }

    /** How a traveller arrives: in a linked exit portal (found or built), or on the first standing spot. */
    public enum Arrival {
        PORTAL,
        SURFACE
    }

    /**
     * Travel: {@code scale} of the destination against {@code return_to} (empty: from the dimension types), the arrival,
     * the survival players' delay (empty: the gamerule), the cooldown after arrival (empty: vanilla's), whether only
     * players travel, and whether the client shows vanilla's wobble and overlay.
     */
    public record Travel(Optional<Double> scale, Arrival arrival, Optional<Integer> delayTicks, Optional<Integer> cooldownTicks,
            boolean playersOnly, boolean overlay) {}

    /** A sound setting: {@code off} for {@code false}; no {@code sound} means the default sound. */
    public record Sound(boolean off, Optional<Identifier> sound) {}

    /** The ambient and travel sounds. */
    public record Sounds(Sound ambient, Sound travel) {}

    /** Particles: a type without options (empty: the portal particle), or dust of {@code color}, and the count per tick. */
    public record Particles(Optional<Identifier> type, Optional<Integer> color, int count) {}
}
`;
}
